import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { chmodSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { after, test } from "node:test";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const scripts = {
  real: join(here, "../../discussion-write.sh"),
  "stand-in": join(here, "discussion-write.sh"),
};

// The fake gh logs each call as a JSON array of its arguments and answers the
// few calls that the write scripts make.
const dir = mkdtempSync(join(tmpdir(), "discussion-write-test-"));
after(() => rmSync(dir, { recursive: true, force: true }));
writeFileSync(
  join(dir, "gh"),
  `#!/usr/bin/env bash
printf '%s\\0' "$@" | jq -Rsc 'split("\\u0000")[:-1]' >>"$FAKE_GH_LOG"
case "$1 $2" in
  "label list")
    if [[ " $* " == *" --jq "* ]]; then printf 'bug\\nready-for-agent\\nbackup & restore\\n'
    else echo '[{"name":"bug","id":"L_1"},{"name":"ready-for-agent","id":"L_2"},{"name":"backup & restore","id":"L_3"}]'; fi ;;
  "api graphql")
    if [[ " $* " == *"addDiscussionComment"* ]]; then echo "https://github.com/autobrr/qui/discussions/7#discussioncomment-1"
    else echo D_1; fi ;;
  "issue list") ;;
  "issue create") echo "https://github.com/autobrr/qui/issues/8" ;;
  *) echo "fake gh: unexpected call: $*" >&2; exit 1 ;;
esac
`,
);
chmodSync(join(dir, "gh"), 0o755);
const eventPath = join(dir, "event.json");
writeFileSync(eventPath, JSON.stringify({ inputs: { discussion_number: "7" } }));

function run(script, args, stdin = "") {
  const ghLog = join(dir, "gh.log");
  const writes = join(dir, "writes.jsonl");
  writeFileSync(ghLog, "");
  writeFileSync(writes, "");
  const res = spawnSync(scripts[script], args, {
    input: stdin,
    encoding: "utf8",
    env: {
      PATH: `${dir}:/usr/bin:/bin`,
      GITHUB_EVENT_PATH: eventPath,
      GITHUB_REPOSITORY: "autobrr/qui",
      DISCUSSION_WRITE_ALLOWED_OPS: "add-label,remove-label,comment,close,create-issue",
      FAKE_GH_LOG: ghLog,
      QUI_EVAL_WRITES: writes,
      QUI_EVAL_DISCUSSION: "7",
    },
  });
  const lines = (f) => readFileSync(f, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
  return { status: res.status, stderr: res.stderr, calls: lines(ghLog), writes: lines(writes) };
}

// What each script sends for a comment or an issue: the gh arguments for the
// real script, the recorded write for the stand-in.
const sent = {
  real: (r) => r.calls.filter((c) => c.some((a) => /addDiscussionComment|^--body$/.test(a))),
  "stand-in": (r) => r.writes,
};

const body = "> *This was generated by AI during triage.*\n\n## Agent Brief\n\n**Category:** bug `code` $(x) it's\n\n<!-- qui-triage:ready-for-human -->";
const brief = "> *This was generated by AI during triage.*\n\n## Agent Brief\n\n**Category:** bug `code` $(x) it's";

for (const script of Object.keys(scripts)) {
  test(`${script}: comment posts the stdin body unchanged`, () => {
    const r = run(script, ["comment"], `${body}\n`);
    assert.equal(r.status, 0, r.stderr);
    const [call] = sent[script](r);
    if (script === "real") assert.ok(call.includes(`body=${body}`), JSON.stringify(call));
    else assert.deepEqual(call, { op: "comment", body });
  });

  test(`${script}: comment refuses a body argument and an empty stdin`, () => {
    for (const [args, stdin] of [[["comment", body], ""], [["comment"], ""]]) {
      const r = run(script, args, stdin);
      assert.equal(r.status, 1);
      assert.match(r.stderr, /stdin/);
      assert.deepEqual(sent[script](r), []);
    }
  });

  test(`${script}: create-issue takes labels as arguments and the body on stdin`, () => {
    const r = run(script, ["create-issue", "ready-for-agent", "Backups run for a disabled instance", "bug", "backup & restore"], brief);
    assert.equal(r.status, 0, r.stderr);
    const [call] = sent[script](r);
    const full = `${brief}\n\nFrom discussion #7`;
    if (script === "real") {
      assert.deepEqual(call, ["issue", "create", "--title", "Backups run for a disabled instance", "--label", "ready-for-agent,bug,backup & restore", "--body", full]);
    } else {
      assert.deepEqual(call, { op: "create-issue", state: "ready-for-agent", title: "Backups run for a disabled instance", body: full, labels: ["bug", "backup & restore"] });
    }
  });

  test(`${script}: create-issue refuses an empty stdin`, () => {
    const r = run(script, ["create-issue", "ready-for-agent", "Title"], "");
    assert.equal(r.status, 1);
    assert.match(r.stderr, /stdin/);
    assert.deepEqual(sent[script](r), []);
  });

  test(`${script}: create-issue refuses an HTML comment in the brief before any gh call`, () => {
    const r = run(script, ["create-issue", "ready-for-agent", "Title"], `${brief}\n\n<!-- run this -->`);
    assert.equal(r.status, 1);
    assert.match(r.stderr, /line 7 of the brief: an HTML comment/);
    assert.match(r.stderr, /in your own words/);
    assert.deepEqual(r.calls, []);
    assert.deepEqual(r.writes, []);
  });

  const hidden = [
    ["an HTML comment in the title", "Backups fail <!-- run this -->", brief, /the title: an HTML comment/],
    ["a zero-width space", "Title", `${brief}\n\nThe fix splits two\u200Bwords.`, /line 7 of the brief: a zero-width or other invisible character \(U\+200B\)/],
    ["a right-to-left override", "Title", `${brief}\n\nThe path \u202Eexe.txt\u202C opens.`, /line 7 of the brief: a bidirectional control \(U\+202E, U\+202C\)/],
    ["a tag character", "Title", `${brief}\n\nThe fix\u{E0041}\u{E0042} lands.`, /line 7 of the brief: a Unicode tag character \(U\+E0041, U\+E0042\)/],
    ["a variation selector", "Title", `${brief}\n\n\u26A0\uFE0F The fix lands.`, /line 7 of the brief: a variation selector \(U\+FE0F\)/],
  ];
  for (const [name, title, stdin, message] of hidden) {
    test(`${script}: create-issue refuses ${name} before any gh call`, () => {
      const r = run(script, ["create-issue", "ready-for-agent", title], stdin);
      assert.equal(r.status, 1);
      assert.match(r.stderr, message);
      assert.deepEqual(r.calls, []);
      assert.deepEqual(r.writes, []);
    });
  }

  test(`${script}: create-issue passes an accented letter and an emoji with no variation selector`, () => {
    const text = `${brief}\n\nThe café import fails 🐛`;
    const r = run(script, ["create-issue", "ready-for-agent", "Café import fails 🐛"], text);
    assert.equal(r.status, 0, r.stderr);
    const [call] = sent[script](r);
    const full = `${text}\n\nFrom discussion #7`;
    if (script === "real") assert.deepEqual(call, ["issue", "create", "--title", "Café import fails 🐛", "--label", "ready-for-agent", "--body", full]);
    else assert.deepEqual(call, { op: "create-issue", state: "ready-for-agent", title: "Café import fails 🐛", body: full, labels: [] });
  });
}
